module WorstRank (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n_minus_one,\n    input wire scores_valid,\n    input wire [7:0] scores_in,\n    input wire is_your_score,\n    input wire end_of_contestants,\n    output reg [7:0] worst_rank,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE     = 3'd0;\n    localparam [2:0] READING  = 3'd1;\n    localparam [2:0] FINISH   = 3'd2;\n    \n    reg [2:0] state;\n    reg [3:0] score_index;\n    reg processing_you;\n    reg [79:0] your_scores_packed;\n    reg [79:0] other_scores_packed;\n    reg [7:0] contestants_read;\n    reg [7:0] counter;\n    reg [15:0] your_aggregate;\n    reg [15:0] other_aggregate;\n    reg [7:0] fourth_highest_other;\n    reg [15:0] needed_score_val;\n\n    // Compute top4 function with packed arrays\n    function automatic void compute_top4(\n        input [79:0] packed_scores,\n        input [3:0] len,\n        output reg [15:0] sum,\n        output reg [7:0] fourth\n    );\n        integer i, j;\n        reg [7:0] scores[0:9];\n        reg [7:0] sorted[0:9];\n        \n        // Unpack input\n        for (i = 0; i < 10; i = i + 1) begin\n            scores[i] = packed_scores[i*8 +: 8];\n        end\n        \n        // Copy and sort descending\n        for (i = 0; i < len; i = i + 1) begin\n            sorted[i] = scores[i];\n        end\n        for (i = 0; i < len-1; i = i + 1) begin\n            for (j = 0; j < len-i-1; j = j + 1) begin\n                if (sorted[j] < sorted[j+1]) begin\n                    sorted[j] = sorted[j] ^ sorted[j+1];\n                    sorted[j+1] = sorted[j] ^ sorted[j+1];\n                    sorted[j] = sorted[j] ^ sorted[j+1];\n                end\n            end\n        end\n        \n        // Compute sum and fourth highest\n        sum = 16'd0;\n        fourth = 8'd0;\n        for (i = 0; i < (len < 4 ? len : 4); i = i + 1) begin\n            sum = sum + sorted[i];\n        end\n        if (len >= 4) fourth = sorted[3];\n    endfunction\n\n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // State control\n            state <= IDLE;\n            done <= 1'b0;\n            worst_rank <= 8'd0;\n            \n            // Data registers\n            score_index <= 4'd0;\n            processing_you <= 1'b1;\n            contestants_read <= 4'd0;\n            counter <= 8'd0;\n            your_scores_packed <= 80'd0;\n            other_scores_packed <= 80'd0;\n            your_aggregate <= 16'd0;\n            other_aggregate <= 16'd0;\n            fourth_highest_other <= 8'd0;\n            needed_score_val <= 16'd0;\n        end\n        else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= READING;\n                        processing_you <= 1'b1;\n                        score_index <= 4'd0;\n                        contestants_read <= 4'd0;\n                        counter <= 8'd0;\n                        your_scores_packed <= 80'd0;\n                        other_scores_packed <= 80'd0;\n                    end\n                end\n                \n                READING: begin\n                    if (scores_valid) begin\n                        if (processing_you) begin\n                            your_scores_packed[score_index*8 +:8] <= scores_in;\n                        end\n                        else begin\n                            other_scores_packed[score_index*8 +:8] <= scores_in;\n                        end\n                        score_index <= score_index + 4'd1;\n                        \n                        // End of current contestant\n                        if (score_index == n_minus_one - 4'd1) begin\n                            score_index <= 4'd0;\n                            \n                            if (processing_you) begin\n                                compute_top4(your_scores_packed, n_minus_one, your_aggregate, fourth_highest_other);\n                                processing_you <= 1'b0;\n                            end\n                            else begin\n                                compute_top4(other_scores_packed, n_minus_one, other_aggregate, fourth_highest_other);\n                                \n                                // Calculate needed score\n                                if (n_minus_one < 4'd3) begin  // n = n_minus_one + 1 < 4\n                                    if (your_aggregate > other_aggregate) begin\n                                        needed_score_val <= (your_aggregate - other_aggregate) + 16'd1;\n                                    end\n                                    else begin\n                                        needed_score_val <= 16'd0;\n                                    end\n                                end\n                                else begin\n                                    if (other_aggregate > your_aggregate) begin\n                                        needed_score_val <= 16'd0;\n                                    end\n                                    else begin\n                                        reg [15:0] val1 = {8'd0, fourth_highest_other} + 16'd1;\n                                        reg [15:0] val2 = (your_aggregate - other_aggregate + fourth_highest_other) + 16'd1;\n                                        needed_score_val <= (val1 > val2) ? val1 : val2;\n                                    end\n                                end\n                                \n                                // Update counter if needed_score is possible\n                                if (needed_score_val <= 16'd101) begin\n                                    counter <= counter + 8'd1;\n                                end\n                                \n                                contestants_read <= contestants_read + 4'd1;\n                                other_scores_packed <= 80'd0;\n                            end\n                        end\n                    end\n                    \n                    // Handle end_of_contestants\n                    if (end_of_contestants && !processing_you && score_index == 4'd0) begin\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    worst_rank <= counter + 8'd1;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule